#include "ModulePage.h"
#include "UI/Theme.h"
namespace vox {
static void moduleLabel(juce::Label&l,float s,juce::Colour c,bool b=false){l.setColour(juce::Label::textColourId,c);l.setFont(juce::Font(juce::FontOptions(s,b?juce::Font::bold:juce::Font::plain)));}
ModulePage::ModulePage(Kind k,AudioEngine&e,PresetManager&p):kind(k),engine(e),presets(p){moduleLabel(title,24,theme::text,true);moduleLabel(description,13,theme::muted);moduleLabel(status,14,theme::text,true);moduleLabel(emptyState,14,theme::muted);for(auto*l:{&title,&description,&status,&emptyState})addAndMakeVisible(l);for(auto*b:{&primary,&secondary,&tertiary})addAndMakeVisible(b);presetList.addItemList(presets.names(),1);addAndMakeVisible(presetList);addAndMakeVisible(soundList);soundProgress.setSliderStyle(juce::Slider::LinearHorizontal);soundProgress.setTextBoxStyle(juce::Slider::NoTextBox,false,0,0);soundProgress.setEnabled(false);soundProgress.setRange(0.0,1.0);addAndMakeVisible(soundProgress);for(auto*s:{&hp,&lp}){s->setSliderStyle(juce::Slider::LinearHorizontal);s->setTextBoxStyle(juce::Slider::TextBoxRight,false,75,24);addAndMakeVisible(s);}setup();startTimerHz(10);}
ModulePage::~ModulePage(){stopTimer();}
void ModulePage::setup(){primary.setColour(juce::TextButton::buttonColourId,theme::blue);switch(kind){case Kind::Home:title.setText("Inicio",juce::dontSendNotification);description.setText("Visao geral do audio e acesso rapido as funcoes principais.",juce::dontSendNotification);primary.setButtonText("Abrir vozes");secondary.setButtonText("Configurar dispositivos");tertiary.setButtonText("Alternar bypass");primary.onClick=[this]{if(navigate)navigate(PageId::Voices);};secondary.onClick=[this]{if(navigate)navigate(PageId::Devices);};tertiary.onClick=[this]{engine.parameters().bypass=!engine.parameters().bypass.load();};break;case Kind::Soundboard:title.setText("Painel de Som",juce::dontSendNotification);description.setText("Importe, selecione e reproduza WAV, MP3, OGG, FLAC, AIFF ou AIF.",juce::dontSendNotification);primary.setButtonText("+ Importar som");secondary.setButtonText("Remover selecionado");tertiary.setButtonText("Reproduzir");secondary.setEnabled(false);tertiary.setEnabled(false);soundList.setTextWhenNothingSelected("Selecione um arquivo importado");soundList.onChange=[this]{selectSound(soundList.getSelectedId()-1);};primary.onClick=[this]{chooser=std::make_unique<juce::FileChooser>("Selecionar arquivo de áudio",juce::File::getSpecialLocation(juce::File::userMusicDirectory),"*.wav;*.mp3;*.ogg;*.flac;*.aiff;*.aif",true);chooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles,[this](const juce::FileChooser&c){auto f=c.getResult();if(!f.existsAsFile()){status.setText("Nenhum arquivo foi selecionado.",juce::dontSendNotification);return;}for(int i=0;i<importedSounds.size();++i)if(importedSounds[i]==f){soundList.setSelectedId(i+1);return;}importedSounds.add(f);soundList.addItem(f.getFileName(),importedSounds.size());soundList.setSelectedId(importedSounds.size());});};secondary.onClick=[this]{const int index=soundList.getSelectedId()-1;if(!juce::isPositiveAndBelow(index,importedSounds.size()))return;engine.stopSoundboard();importedSounds.remove(index);soundList.clear();for(int i=0;i<importedSounds.size();++i)soundList.addItem(importedSounds[i].getFileName(),i+1);selectedSound={};secondary.setEnabled(false);tertiary.setEnabled(false);status.setText("Arquivo removido da lista.",juce::dontSendNotification);emptyState.setText(importedSounds.isEmpty()?"Nenhum som importado. Clique em + Importar som.":"Selecione outro arquivo na lista.",juce::dontSendNotification);};tertiary.onClick=[this]{if(selectedSound.existsAsFile()){if(engine.isSoundboardPlaying())engine.stopSoundboard();else engine.playSoundboard();}};emptyState.setText("Nenhum som importado. Clique em + Importar som para começar.",juce::dontSendNotification);break;case Kind::Favorites:title.setText("Favoritos",juce::dontSendNotification);description.setText("Vozes, efeitos, sons e presets marcados como favoritos.",juce::dontSendNotification);primary.setVisible(false);secondary.setVisible(false);tertiary.setVisible(false);emptyState.setText("Nenhum favorito salvo. Marque itens na biblioteca para eles aparecerem aqui.",juce::dontSendNotification);break;case Kind::Equalizer:title.setText("Equalizador",juce::dontSendNotification);description.setText("Filtros globais conectados ao processamento real.",juce::dontSendNotification);primary.setButtonText("Redefinir filtros");secondary.setVisible(false);tertiary.setVisible(false);hp.setRange(20,2000,1);lp.setRange(2000,20000,10);hp.setValue(engine.parameters().hpFreq.load(),juce::dontSendNotification);lp.setValue(engine.parameters().lpFreq.load(),juce::dontSendNotification);hp.onValueChange=[this]{engine.parameters().hpFreq=(float)hp.getValue();};lp.onValueChange=[this]{engine.parameters().lpFreq=(float)lp.getValue();};primary.onClick=[this]{hp.setValue(70);lp.setValue(18000);};emptyState.setText("Passa-altas                                      Passa-baixas",juce::dontSendNotification);break;case Kind::Presets:title.setText("Presets",juce::dontSendNotification);description.setText("Carregue ou salve configuracoes de voz em JSON.",juce::dontSendNotification);primary.setButtonText("Aplicar preset");secondary.setButtonText("Salvar copia");tertiary.setVisible(false);primary.onClick=[this]{if(presetList.getSelectedId()>0){presets.load(presetList.getText(),engine.parameters());status.setText("Preset aplicado: "+presetList.getText(),juce::dontSendNotification);}};secondary.onClick=[this]{auto name=presetList.getText().isNotEmpty()?presetList.getText()+" - copia":"Meu preset";presets.save(name,engine.parameters());presetList.clear();presetList.addItemList(presets.names(),1);status.setText("Preset salvo: "+name,juce::dontSendNotification);};break;}}
void ModulePage::selectSound(int index){if(!juce::isPositiveAndBelow(index,importedSounds.size()))return;selectedSound=importedSounds[index];auto error=engine.loadSoundboardFile(selectedSound);if(error.isNotEmpty()){status.setText(error,juce::dontSendNotification);secondary.setEnabled(true);tertiary.setEnabled(false);return;}secondary.setEnabled(true);tertiary.setEnabled(true);emptyState.setText("Arquivo selecionado: "+selectedSound.getFileName()+"\nUse Reproduzir para enviar o som à saída configurada.",juce::dontSendNotification);status.setText("Pronto para reproduzir.",juce::dontSendNotification);}
void ModulePage::timerCallback(){if(kind==Kind::Soundboard){const auto duration=engine.soundboardDuration();const auto position=engine.soundboardPosition();soundProgress.setValue(duration>0.0?position/duration:0.0,juce::dontSendNotification);tertiary.setButtonText(engine.isSoundboardPlaying()?"Parar":"Reproduzir");if(selectedSound.existsAsFile())status.setText((engine.isSoundboardPlaying()?"Reproduzindo: ":"Selecionado: ")+selectedSound.getFileName()+"   "+juce::String(position,1)+" / "+juce::String(duration,1)+" s",juce::dontSendNotification);return;}if(kind!=Kind::Home)return;auto*d=engine.deviceManager().getCurrentAudioDevice();juce::String text="Processamento: "+juce::String(engine.isRunning()?"ATIVO":"DESLIGADO")+"\n";text+="Dispositivo: "+(d?d->getName():"Nao disponivel")+"\n";if(d)text+="Sample rate: "+juce::String(d->getCurrentSampleRate(),0)+" Hz   Buffer: "+juce::String(d->getCurrentBufferSizeSamples())+"\n";text+="CPU DSP: "+juce::String(engine.cpuUsage()*100,1)+"%   Underruns: "+juce::String((juce::int64)engine.underruns());status.setText(text,juce::dontSendNotification);}
void ModulePage::paint(juce::Graphics&g){g.fillAll(theme::background);for(auto r:panels)theme::roundedPanel(g,r.toFloat(),12,theme::panel);if(kind==Kind::Equalizer&&panels.size()>0){auto graph=panels[0].toFloat().reduced(24,50);g.setColour(theme::border);for(int i=0;i<8;++i)g.drawVerticalLine((int)(graph.getX()+i*graph.getWidth()/7),graph.getY(),graph.getBottom());juce::Path curve;curve.startNewSubPath(graph.getX(),graph.getCentreY()+20);curve.cubicTo(graph.getX()+graph.getWidth()*.2f,graph.getCentreY()-15,graph.getX()+graph.getWidth()*.7f,graph.getCentreY(),graph.getRight(),graph.getCentreY()-8);g.setColour(theme::cyan);g.strokePath(curve,juce::PathStrokeType(2));}}
void ModulePage::resized(){auto a=getLocalBounds().reduced(18);title.setBounds(a.removeFromTop(34));description.setBounds(a.removeFromTop(28));auto buttons=a.removeFromTop(48);primary.setBounds(buttons.removeFromLeft(180).reduced(3));secondary.setBounds(buttons.removeFromLeft(190).reduced(3));tertiary.setBounds(buttons.removeFromLeft(150).reduced(3));a.removeFromTop(10);panels.clear();panels.add(a);auto content=a.reduced(24);soundList.setBounds({});soundProgress.setBounds({});if(kind==Kind::Home){status.setBounds(content.removeFromTop(150));emptyState.setText("Acoes rapidas usam dados reais do AudioEngine.",juce::dontSendNotification);emptyState.setBounds(content.removeFromTop(50));}else if(kind==Kind::Soundboard){soundList.setBounds(content.removeFromTop(42));content.removeFromTop(10);emptyState.setBounds(content.removeFromTop(65));status.setBounds(content.removeFromTop(36));soundProgress.setBounds(content.removeFromTop(28));presetList.setBounds({});}else if(kind==Kind::Equalizer){emptyState.setBounds(content.removeFromTop(35));hp.setBounds(content.removeFromTop(48));lp.setBounds(content.removeFromTop(48));status.setBounds({});presetList.setBounds({});}else if(kind==Kind::Presets){presetList.setBounds(content.removeFromTop(42));status.setBounds(content.removeFromTop(60));emptyState.setBounds({});}else{emptyState.setBounds(content.removeFromTop(110));status.setBounds({});presetList.setBounds({});}if(kind!=Kind::Equalizer){hp.setBounds({});lp.setBounds({});}}
}
